#!/usr/bin/env python3
"""Korea code/policy installation only. No Binance call, database write or timer activation."""
import os,sys,json,gzip,base64,hashlib,subprocess,tempfile,stat,datetime,fcntl,shutil
from pathlib import Path
PAYLOAD = ''

ROOT=Path('/opt/xuanjun-migration-s07/releases/korea-model-handoff-v1/app')
CONFIG=Path('/home/admin/.openclaw/workspace/xuanjun-agent-coordination/CUSTOMER_REFERRAL_CONFIG.json')
CHILD=r'''
import sys,json,ast,hashlib
from pathlib import Path
p=json.loads(sys.stdin.read())
ns={'__name__':'fee_library'}
exec(compile(p['fee_helpers'],'fee_library','exec'),ns)
files=dict(p['files'])
fee=json.loads(p['config'])
if fee.get('fee_policy_id')=='OWNER_FEE_POLICY_20261020_20_0_70_V1':
    if hashlib.sha256(p['foundation'].encode()).hexdigest()!='f133fbb83308410681fc8618cbe5a0797e0a1ca3357e89c310cd7cf7f6c793e5':
        raise ValueError('FEE_SOURCE_VERSION_MISMATCH')
    files['trading_execution/business_fee_foundation.py']=p['foundation']
else:
    files['trading_execution/business_fee_foundation.py']=ns['patch_foundation'](p['foundation'])
files['@CONFIG']=json.dumps(ns['policy_config'](fee),ensure_ascii=False,indent=2)+'\n'
if 'service_fee_rate=0.0,' not in p['preview']:
    files['trading_execution/billing_preview.py']=ns['patch_preview'](p['preview'])
exec(compile(p['weekly_helpers'],'weekly_helpers','exec'),ns)
if hashlib.sha256(p['production'].encode()).hexdigest()!=p['weekly_original_sha']:
    raise ValueError('KOREA_WEEKLY_SOURCE_VERSION_MISMATCH')
files['trading_execution/production_activation.py']=ns['patch_production'](p['production'])
files['trading_execution/weekly_rebate_window.py']=p['weekly_runtime']
scope={"ast":ast}
exec(compile(p['checks'],'billing_checks','exec'),scope)
result=scope['checks'](files)
for name,text in files.items():
    if name.endswith('.py'):compile(text,name,'exec')
assert 'PAYMENT_DUE_HOURS_FROM_ACTUAL_INVOICE_SENT_AT = 24' in files['trading_execution/business_fee_foundation.py']
print(json.dumps({'files':files,'checks':result},ensure_ascii=False))
'''

def atomic(p,data,mode,uid,gid):
    fd,tmp=tempfile.mkstemp(prefix='.billing-policy-',dir=str(p.parent))
    try:
        os.fchmod(fd,mode);os.fchown(fd,uid,gid)
        with os.fdopen(fd,'wb') as f:
            f.write(data);f.flush();os.fsync(f.fileno())
        os.replace(tmp,str(p))
    finally:
        if os.path.exists(tmp):os.unlink(tmp)

def main():
    if os.geteuid()!=0 or os.uname().nodename.split('.')[0]!='iZmj7a5kwr75qc1tul4kf9Z':
        raise SystemExit('HOLD_NOT_KOREA')
    os.umask(0o077)
    lock=open('/run/xuanjun-korea-billing-code.lock','a')
    fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    payload=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    if not CONFIG.is_file() or CONFIG.is_symlink():
        raise SystemExit('HOLD_ORIGINAL_AUTHORITY_CONFIG_MISSING:'+str(CONFIG))
    if (ROOT/'trading_execution/billing_overdue_policy.py').exists():
        raise SystemExit('HOLD_ALREADY_INSTALLED_USE_EXISTING_CHECKPOINT')
    originals={}
    for rel,digest in payload['original_sha'].items():
        p=ROOT/rel
        if not p.is_file() or p.is_symlink():raise SystemExit('HOLD_SOURCE:'+rel)
        raw=p.read_bytes()
        if hashlib.sha256(raw).hexdigest()!=digest:raise SystemExit('HOLD_SOURCE_CHANGED:'+rel)
        originals[p]=raw
    for key,rel in (('foundation','trading_execution/business_fee_foundation.py'),('preview','trading_execution/billing_preview.py'),('production','trading_execution/production_activation.py')):
        p=ROOT/rel
        if not p.is_file() or p.is_symlink():raise SystemExit('HOLD_SOURCE:'+rel)
        raw=p.read_bytes();originals[p]=raw;payload[key]=raw.decode()
    originals[CONFIG]=CONFIG.read_bytes();payload['config']=originals[CONFIG].decode()
    nsenter=shutil.which('nsenter')
    if nsenter is None:raise SystemExit('HOLD_EXISTING_RUNTIME_ENTRY_MISSING')
    r=subprocess.run(['systemctl','show','pr99-korea-model-rpc.service','--property=MainPID','--value'],
        stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True,timeout=10)
    pid=r.stdout.strip()
    if r.returncode or not pid.isdigit() or pid=='0':raise SystemExit('HOLD_MODEL_RUNTIME_NOT_RUNNING')
    mount=(Path('/proc')/pid/'mountinfo').read_text()
    if not any(len(x.split())>5 and x.split()[3]==str(ROOT) and x.split()[4]=='/opt/trading-system' for x in mount.splitlines()):
        raise SystemExit('HOLD_CURRENT_MOUNT_BINDING_CHANGED')
    result=subprocess.run([nsenter,'--target',pid,'--mount','--','/bin/python3.11','-I','-B','-S','-c',CHILD],
        input=json.dumps(payload,ensure_ascii=False),stdout=subprocess.PIPE,stderr=subprocess.PIPE,
        universal_newlines=True,timeout=45)
    checkpoint=Path('/root')/('xuanjun-korea-billing-'+datetime.datetime.utcnow().strftime('%Y%m%dT%H%M%S%fZ'))
    checkpoint.mkdir(mode=0o700)
    (checkpoint/'offline-check.private.log').write_text(result.stderr)
    print('CHECKPOINT:',str(checkpoint),flush=True)
    if result.returncode:
        print('HOLD_OFFLINE_CHECK_FAILED; PRIVATE_LOG:',str(checkpoint/'offline-check.private.log'))
        raise SystemExit(2)
    prepared=json.loads(result.stdout)
    print(prepared['checks'],flush=True)
    candidates={CONFIG if k=='@CONFIG' else ROOT/k:v.encode() for k,v in prepared['files'].items()}
    doc=CONFIG.parent/'CURRENT_BILLING_EXCEPTION_POLICY.md'
    candidates[doc]=('''# 账单核销及逾期恢复规则

账单实际发出后24小时为逾期停新仓阈值，不是核销有效期。
24小时内财务核销完成，保持正常开仓；超过24小时未核销，列为异常并停止新开仓。
已有仓位继续按原计划管理，止盈、止损、减仓及保护性退出不因欠费被禁止。
逾期后仍接受付款和财务核销。付清服务费、财务核销、客户异常确认三项依次完成后，
才允许解除账单导致的新开仓限制；其他风险/人工交易异常不能因此一并解除。
聊天中的“已付款”不能作为核销依据，客户确认也不能代替财务三方核验。
原数据库保存核销及客户确认引用，开仓入口逐次读取，重启不会清除账单限制。
收费为交易利润20%，跟单利润服务费永久0%，跟单手续费返佣70%。
周一北京时间08:00带单凭据GET快照；15:00只读凭据查询当天08:00至15:00返佣。
本次只安装韩国代码及规则；未改数据库、凭据、模型服务、东京任务或启用财务定时器。
韩国数据库接管、实际API和真实客户交付仍待验收。
''').encode()
    originals[doc]=doc.read_bytes() if doc.exists() else None
    for p,raw in candidates.items():
        if p not in originals:
            if p.exists() or p.is_symlink():raise SystemExit('HOLD_EXISTING_NEW_FILE:'+str(p))
            originals[p]=None
    entries=[]
    for index,(p,raw) in enumerate(candidates.items()):
        old=originals[p]
        st=p.stat() if old is not None else (CONFIG.stat() if p==doc else (ROOT/'risk/account_gate.py').stat())
        entries.append((p,raw,old,stat.S_IMODE(st.st_mode),st.st_uid,st.st_gid))
        if old is not None:(checkpoint/(str(index)+'.original')).write_bytes(old)
    (checkpoint/'manifest.json').write_text(json.dumps([{'path':str(p),'mode':mode,'uid':uid,'gid':gid,
        'existed':old is not None,'original_sha256':hashlib.sha256(old).hexdigest() if old is not None else None,
        'candidate_sha256':hashlib.sha256(raw).hexdigest()} for p,raw,old,mode,uid,gid in entries],indent=2))
    changed=[]
    try:
        for p,raw,old,mode,uid,gid in entries:
            if (p.read_bytes() if p.exists() else None)!=old:raise ValueError('CONCURRENT_SOURCE_CHANGE')
            atomic(p,raw,mode,uid,gid);changed.append((p,raw,old,mode,uid,gid))
        for p,raw,*rest in entries:
            if p.read_bytes()!=raw:raise ValueError('WRITTEN_CONTENT_MISMATCH')
        print('KOREA_CODE_AND_POLICY_UPDATED: FEES_20_0_70; MONDAY_08_15; OVERDUE_RECONCILIATION_AND_CUSTOMER_RESUME')
        print('NO_DATABASE_WRITES; NO_BINANCE_CALLS; NO_MODEL_RESTARTS; NO_TIMER_ACTIVATION')
        print('LIVE_FINANCE_TAKEOVER_AND_END_TO_END_ACCEPTANCE_PENDING')
    except Exception as exc:
        failures=[]
        for p,raw,old,mode,uid,gid in reversed(changed):
            try:
                if p.read_bytes()!=raw:raise ValueError('CONCURRENT_CHANGE')
                if old is None:p.unlink()
                else:atomic(p,old,mode,uid,gid)
            except Exception:failures.append(str(p))
        print('INSTALL_FAILED:',type(exc).__name__,'RESTORE_FAILURES:',json.dumps(failures),'CHECKPOINT:',str(checkpoint))
        raise SystemExit(2)
if __name__=='__main__':main()
